sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (newValue === '') {
        if (g_form.getValue('swift_linking_reference_id_ref') == '') {
            g_form.setMandatory('swift_linking_reference_id_ref', false);
            g_form.setDisplay('swift_linking_reference_id_ref', false);
            g_form.clearValue('swift_linking_reference_id_ref');
            g_form.setValue('swift_linking_reference', "");
        }
        return;
    }

    g_form.setMandatory('swift_linking_reference', true);
    if (oldValue != newValue) {
        g_form.setValue('swift_linking_reference', "");
    }
    try {
        //Limiting the logic to markets other than DCC UK and GC UK as part of MSSCUSTODY-3916

        var ukOwningBusiness = g_scratchpad.owningBus.toString(); //added as part of MSSCUSTODY-3916
        var gbRegex = /UK/; //added as part of MSSCUSTODY-3916

        if (!gbRegex.test(ukOwningBusiness)) { //added as part of MSSCUSTODY-3916

            // Validation on Tran Reference for SWIFT Linking field based on given format.
            var swiftLinking = newValue;
            var tradeID = g_form.getValue('trade_id');
            var RegularExp = /^[RD]-[0-9]{6}-[0-9][0-9]-[0-9]$/;
            var result = RegularExp.test(swiftLinking);
            if (result == false) {
                // MSSCUSTODY 2472
                g_form.addErrorMessage("Invalid Tran Reference. Please ensure it starts with R/D as per the trade type in the format D-NNNNNN-NN-N or R-NNNNNN-NN-N");
                g_form.setValue('tran_reference_for_swift_linking', '');
            } else {
                g_form.clearMessages();
                var trigger_by = g_scratchpad.triggerby;
                var code = trigger_by.slice(0, 5);
                var ref_id = swiftLinking.slice(0, 1);
                //MT544 To MT547 Settl Conf Rev Rejected swifts linking Validation MSSCUSTODY-3669
                var isRev = trigger_by.slice(17, 20);
                if ((code == 'MT544' || code == 'MT545') && isRev == 'Rev' && ref_id != 'D') {
                    g_form.addErrorMessage("Invalid Tran Reference. Please ensure it starts with R/D as per the trade type");
                    g_form.setValue('tran_reference_for_swift_linking', '');

                } else if ((code == 'MT546' || code == 'MT547') && isRev == 'Rev' && ref_id != 'R') {
                    g_form.addErrorMessage("Invalid Tran Reference. Please ensure it starts with R/D as per the trade type");
                    g_form.setValue('tran_reference_for_swift_linking', '');

                } else if ((code == 'MT540' || code == 'MT541' || code == 'MT544' || code == 'MT545') && isRev != 'Rev' && ref_id != 'R') {
                    g_form.addErrorMessage("Invalid Tran Reference. Please ensure it starts with R/D as per the trade type");
                    g_form.setValue('tran_reference_for_swift_linking', '');

                } else if ((code == 'MT542' || code == 'MT543' || code == 'MT546' || code == 'MT547') && isRev != 'Rev' && ref_id != 'D') {
                    g_form.addErrorMessage("Invalid Tran Reference. Please ensure it starts with R/D as per the trade type");
                    g_form.setValue('tran_reference_for_swift_linking', '');

                } else {
                //    alert('calling migration script');
                    g_form.clearMessages();
                    var tradeCheck = new GlideAjax('x_hsb11_mss_c_proc.hsbcTranSwiftLinking');
                    tradeCheck.addParam('sysparm_name', 'validateTrade');
                    tradeCheck.addParam('sysparm_trade_ref_id', swiftLinking);
                    tradeCheck.addParam('sysparm_dummy_trade_market', g_scratchpad.owningBus);
                    tradeCheck.getXMLAnswer(getTradeDetailsChk);
                    g_scratchpad.getTradeDetailsCheck = false;
                }
            }
        } //added as part of MSSCUSTODY-3916
    } catch (error) {}

    function getTradeDetailsChk(response) {

        var retValue = response;
        //alert("Return value is" + retValue);
        if (retValue == 'multiple') {
            g_form.hideFieldMsg('swift_linking_reference_id_ref');

            // MSSCUSTODY-7577
            if (g_form.getValue('trade_task_type') == 'Maker' && (g_form.getValue('state') == '1' || g_form.getValue('state') == '2')) {
                g_form.showFieldMsg('swift_linking_reference_id_ref', 'Multiple Trades found with the entered reference ID, please select the correct one');
            } else if ((g_form.getValue('trade_task_type') == 'Maker' && g_form.getValue('state') == '3') || (g_form.getValue('trade_task_type') == 'Checker') || (g_form.getValue('trade_task_type').indexOf('GHSS Handler') > -1)) {
                g_form.hideFieldMsg('swift_linking_reference_id_ref');
            }

          //  alert('multiple');
            g_form.setDisplay('swift_linking_reference_id', false);
            g_form.setValue('swift_linking_reference_id', "");
            g_form.setDisplay('swift_linking_reference', false); //Added as part of MSSCUSTODY-3122
            g_form.setMandatory('swift_linking_reference', false); // MSSCUSTODY-7577
            g_form.setValue('swift_linking_reference', ""); //Added as part of MSSCUSTODY-3122
            g_form.setDisplay('swift_linking_reference_id_ref', true);
            g_form.setMandatory('swift_linking_reference_id_ref', true);
            //loadingDialog.destroy(); //Destroy Loading Screen


        } else if (retValue == 'no record') {
            g_form.hideFieldMsg('swift_linking_reference_id_ref');
            var tradeID = g_form.getValue('trade_id');
            g_form.setValue('swift_linking_reference_id_ref', "");
            g_form.setMandatory('swift_linking_reference_id_ref', false);
            g_form.setDisplay('swift_linking_reference_id_ref', false);
            g_form.setDisplay('swift_linking_reference_id', true);
            g_form.setDisplay('swift_linking_reference', false); //Added as part of MSSCUSTODY-3122
            var owningBusiness = g_scratchpad.owningBus;
            var country = owningBusiness.split(" ");
            var market = country[0].toString();
            var countryCode = country[1];
            if (market == 'DCC') {
                var entityCode = 'HSBC';
            } else if (market == 'GC') {
                entityCode = 'HIFS';
            }
            var currentDate = new Date();
            var year = currentDate.getFullYear();
            var day = ("0" + currentDate.getDate()).slice(-2);
            var month = ("0" + (currentDate.getMonth() + 1)).slice(-2);
            var swiftReference = countryCode + "-" + entityCode + "-" + swiftLinking + "-" + year + month + day;
            g_form.setValue("swift_linking_reference_id", swiftReference);
            g_form.setValue("swift_linking_reference", swiftReference); //Added as part of MSSCUSTODY-3122
            //loadingDialog.destroy(); //Destroy Loading Screen
        } else {
            g_form.hideFieldMsg('swift_linking_reference_id_ref');
            g_form.setMandatory('swift_linking_reference_id_ref', false);
            g_form.setDisplay('swift_linking_reference_id_ref', false);
         //   alert(retValue);
            g_form.setValue('swift_linking_reference_id', retValue); //Modified as part of MSSCUSTODY-3122.
         //   alert(g_form.getValue('swift_linking_reference_id'));
            g_form.setDisplay('swift_linking_reference_id', false); //Modified as part of MSSCUSTODY-3122.
            g_form.setDisplay('swift_linking_reference', true); //Added as part of MSSCUSTODY-3122.
            //loadingDialog.destroy(); //Destroy Loading Screen

        }

        g_scratchpad.getTradeDetailsCheck = true;
        if (g_scratchpad.SubmitCliked == true) {
            g_form.submit(g_scratchpad.actName);
        }
    }

    if (!gbRegex.test(ukOwningBusiness)) { // limited for wrong mapping

        //Added as part of MSSCUSTODY-3122 // added for Swift Reference 
        var trade = new GlideAjax('HSBCTradeTaskUtils');
        trade.addParam('sysparm_name', 'getTradeID');
        //trade.addParam('sysparm_trade_id', swiftLinking);
        trade.addParam('sysparm_trade_ref_id', swiftLinking);
        trade.addParam('sysparm_dummy_trade_market', g_scratchpad.owningBus);
        trade.getXMLAnswer(getTradeInfo);
    }

    function getTradeInfo(response) {
        if (response == 'multiple') {
            g_form.setDisplay('swift_linking_reference', false); //Added as part of MSSCUSTODY-3122
            g_form.setMandatory('swift_linking_reference', false); // MSSCUSTODY-7577
            g_form.setValue('swift_linking_reference', "");
        } else if (response == 'no record') {
            g_form.showFieldMsg('tran_reference_for_swift_linking', 'Please select a valid trade of ' + g_scratchpad.owningBus + ' market.'); //Defect Fixes - MSSCUSTODY-5435

        } else {
            g_form.setValue('swift_linking_reference', response);

        }
    }


}
